import mongoose from "mongoose";

/**
 * A notice from SukuuPay to the schools, or to the people who run them.
 *
 * Distinct from `Notification`, and the distinction is what makes this collection
 * worth having. A `Notification` is per-recipient, generated by the system when
 * something happens *to you* — a payment landed, a plan was accepted. It is written
 * by code, addressed to one account, and disappears when read.
 *
 * An announcement is authored by a person, aimed at a *population*, and outlives
 * the session that posted it. Maintenance windows, a Hubtel outage, a pricing
 * change: all of them are things every school needs to know at once and none of
 * them are events in anybody's personal feed.
 *
 * **Audiences are mutually exclusive on purpose.** `all_schools` and
 * `selected_schools` are about *who*, `all_admins` is about *which people within
 * them*. A message is either addressed to tenants or to the humans who operate
 * them — never to a school's head teacher as a tenant *and* to its bursar as an
 * admin, because the two render in different places and a single set of screens
 * cannot honour both. `targetSchoolIds` is therefore only read when the audience is
 * `selected_schools`, and the validation layer rejects it otherwise rather than
 * storing a list that will never be consulted.
 *
 * **Scheduled, not published.** `startsAt`/`endsAt` plus `isActive` means a message
 * can be written on Friday for a Monday migration, and `GET /admin/announcements`
 * with `active=true` is a pure date comparison rather than a cron job. A scheduled
 * announcement that also needed a job to publish it would add a failure mode —
 * "the job didn't run, so nobody was told" — in exchange for no behaviour the dates
 * do not already provide.
 */
const platformAnnouncementSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: true,
      trim: true,
      maxlength: 150,
    },

    /**
     * The notice itself.
     *
     * Rendered as plain text, so it must not carry markup. Anything that
     * interprets it as HTML makes the platform console a stored-XSS vector aimed at
     * the only account that can read every school — which is precisely the account
     * worth targeting.
     */
    body: {
      type: String,
      required: true,
      trim: true,
      maxlength: 2000,
    },

    /**
     * How loudly this should read.
     *
     * `critical` is not decoration: it is the one value a console may surface
     * above the fold or in a banner, and it is what an operator reaches for during
     * an outage. Three levels rather than a boolean because "worth mentioning" and
     * "read this now" are different asks.
     */
    severity: {
      type: String,
      enum: ["info", "warning", "critical"],
      default: "info",
      index: true,
    },

    targetAudience: {
      type: String,
      enum: ["all_schools", "selected_schools", "all_admins"],
      default: "all_schools",
      index: true,
    },

    /**
     * The recipients, when the audience is `selected_schools`.
     *
     * Defaulted to `[]` rather than left undefined so "no ids" is a stored value
     * rather than a missing field that two readers can disagree about.
     */
    targetSchoolIds: {
      type: [
        {
          type: mongoose.Schema.Types.ObjectId,
          ref: "School",
        },
      ],
      default: [],
    },

    /**
     * When the notice becomes visible.
     *
     * Required rather than defaulted to now, so scheduling a future message is the
     * same write as publishing one today. The only difference is the value.
     */
    startsAt: {
      type: Date,
      required: true,
      index: true,
    },

    /**
     * When it stops. `null` means "until somebody turns it off", which is the
     * normal state for a standing notice and the only one a plain about-the-platform
     * message needs.
     */
    endsAt: {
      type: Date,
      default: null,
    },

    /**
     * The manual switch, separate from the window.
     *
     * Needed because the window cannot express the other two cases: withdrawing a
     * notice before it starts, and taking down a wrong announcement immediately
     * rather than at `endsAt`. Both are edits that must not require rewriting dates.
     */
    isActive: {
      type: Boolean,
      default: true,
      index: true,
    },

    /** Who wrote it. A reference, not a copy — see `PlatformSettings.updatedBy`. */
    createdBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },
  },
  { timestamps: true }
);

/*
 * The console's default read: "what is live right now", newest first.
 *
 * `{ isActive: 1, startsAt: -1 }` serves it directly. `isActive` is already indexed
 * on its own and the query adds a *range* on `startsAt` — Mongo can use one index
 * for a range, so the compound is what avoids fetching every inactive row to find
 * the newest active one.
 */
platformAnnouncementSchema.index({ isActive: 1, startsAt: -1 });

/*
 * Resolving an audience for one school ("does this notice concern you?") is the
 * read behind the per-school banner, and it is `targetSchoolIds` plus a date test.
 * Multikey, so only one array field may be in a compound index.
 */
platformAnnouncementSchema.index({ targetSchoolIds: 1, startsAt: -1 });

platformAnnouncementSchema.set("toJSON", {
  virtuals: true,
  transform: (_doc, ret) => {
    delete ret.__v;
    return ret;
  },
});

export const PlatformAnnouncement = mongoose.model(
  "PlatformAnnouncement",
  platformAnnouncementSchema
);

/**
 * Whether an announcement is visible at a given instant.
 *
 * Exported so the "is this live?" test has exactly one implementation. It appears
 * in the console's list filter, in the per-school resolution query, and in the
 * creation path that rejects a window ending before it starts — and three
 * hand-written copies of `startsAt <= now && (!endsAt || endsAt > now)` is three
 * chances to disagree about whether a notice about to expire counts as live.
 *
 * `endsAt` is exclusive: a notice whose window closed at 09:00 is not live at
 * 09:00. Inclusive would make two adjacent windows both claim 09:00.
 */
export const isAnnouncementLive = (announcement, now = new Date()) => {
  if (!announcement?.isActive) return false;
  const at = now.getTime();
  if (new Date(announcement.startsAt).getTime() > at) return false;
  if (announcement.endsAt && new Date(announcement.endsAt).getTime() <= at) return false;
  return true;
};

export default PlatformAnnouncement;